import { Color } from '../../../mol-util/color/index.js';
export interface Kinemage {
    readonly comments: ReadonlyArray<string>;
    kinemage?: number;
    onewidth?: any;
    viewDict: {
        [id: number]: View;
    };
    pdbfile?: string;
    text: string;
    texts: string[];
    captions: string[];
    caption: string;
    groupDict: {
        [k: string]: {
            [k: string]: boolean;
        };
    };
    subgroupDict: {
        [k: string]: any;
    };
    masterDict: {
        [k: string]: {
            indent: boolean;
            visible: boolean;
        };
    };
    pointmasterDict: {
        [k: string]: string;
    };
    dotLists: DotList[];
    vectorLists: VectorList[];
    ballLists: BallList[];
    ribbonLists: RibbonObject[];
    groupsAnimate: string[];
    activeAnimateGroup: number;
    groupsAnimate2: string[];
    activeAnimateGroup2: number;
    viewSnapshots?: {};
}
/** Common base for all list-like objects in a kinemage */
export interface KinListBase {
    name?: string;
    group: string;
    subgroup: string;
    nobutton: boolean;
    masterArray: any[];
    pointmasterArray: string[][];
}
export interface DotList extends KinListBase {
    labelArray: string[];
    positionArray: number[];
    colorArray: Color[];
}
export interface BallList extends KinListBase {
    labelArray: string[];
    positionArray: number[];
    colorArray: Color[];
    radiusArray: number[];
}
export interface RibbonObject extends KinListBase {
    labelArray: string[];
    positionArray: number[];
    colorArray: Color[];
    breakArray: boolean[];
    pairTriangleNormals: boolean;
}
export interface VectorList extends KinListBase {
    label1Array: string[];
    label2Array: string[];
    position1Array: number[];
    position2Array: number[];
    color1Array: Color[];
    color2Array: Color[];
    width: number[];
}
export interface View {
    name?: string;
    center?: number[];
    matrix?: number[];
    span?: number;
    zoom?: number;
    zslab?: number;
}
